{"cruxes": [{"issue": "Whether nuclear power stations should be built despite environmental and health risks",
  "side_a": "Nuclear power stations should be built, especially to reduce energy dependence and ensure sustainable electricity supply, given strict safety controls and rare accident occurrences",
  "members_a": [3],
  "side_b": "Nuclear power stations should not be built, or at least not without exhaustive evaluation and exhausting all alternatives, due to serious concerns about environmental impact, public health, and long-term risks including rare but catastrophic accidents",
  "members_b": [1, 2, 4, 5]
}]}

{"cruxes": [{"issue": "Whether to ban or allow offshore wind turbines on the UK shoreline",
  "side_a": "Should not ban offshore wind turbines due to their importance for renewable energy, climate goals, and energy security",
  "members_a": [2, 3, 4, 5],
  "side_b": "While recognizing renewable benefits, some express concern about environmental impact and suggest a case-by-case approach or possible restrictions",
  "members_b": [5]
}]}

{"cruxes": [{"issue": "Whether sugary drinks should be restricted by law or policy",
  "side_a": "Sugary drinks should be restricted, including through government regulation, due to health and economic costs",
  "members_a": [1, 2, 5],
  "side_b": "Sugary drinks should not be restricted, or only minimally regulated, respecting personal choice",
  "members_b": [3, 4]
}]}

{"cruxes": [{"issue": "Whether offering special scholarships to high-earning students is a justified and effective policy to encourage them to stay in the UK",
  "side_a": "Offering scholarships to high-earning students is justified and beneficial because they bring valuable skills, contribute to the economy, and can innovate and train others.",
  "members_a": [3, 4],
  "side_b": "Offering scholarships to high-earning students is a severe waste of money; instead, the focus should be on making the UK naturally appealing through better universities and job markets, and students will decide independently based on broader factors.",
  "members_b": [2, 5]
}]}
